from lib import *
recs=[
R(2292,"Punch Sherbet Jeruk-Nanas",
"Punch Sherbet Jeruk-Nanas pasti menjadi favorit pesta pada acara sosial Anda berikutnya. Ahli gizi DaVita, Bonnie dari Texas, menemukan resep ini dan membuat Punch Sherbet Jeruk-Nanas untuk sebuah pesta guna membantu pasien dialisisnya memperbaiki kontrol fosfor.",
"22","6 ons",
["1 cangkir jus jeruk-nanas","1/2 galon sherbet, rasa sesuai pilihan Anda","1 botol 2 liter soda diet lemon-lime berkarbonasi, dingin"],
["Campurkan jus dan sherbet dalam mangkuk punch.","Isi sisa mangkuk dengan soda lemon-lime."],
["Gunakan soda manis jika diinginkan untuk tambahan kalori.","Aduk punch agar tidak berbusa saat sherbet mencair.","Tambahkan es batu cincin agar punch tetap dingin."],
["1/2 buah, kalium rendah","1 berkalori tinggi"]),
R(2293,"Burger Kalkun Berbumbu",
"Anda mungkin sudah pernah mencoba burger sapi klasik dari ahli gizi DaVita, Lisa. Ia telah menciptakan resep baru yang ramah ginjal untuk burger kalkun berbumbu. Burger kalkun rendah natrium ini cukup lezat untuk dimakan tanpa roti dan saus pelengkap, tetapi silakan tambahkan roti dan topping jika diinginkan.",
"4","1 burger",
["1 pon daging kalkun giling tanpa lemak","1/2 cangkir remah roti panko","1/4 cangkir bawang merah besar","1 butir telur besar","1/2 sendok teh cabai merah tumbuk","1/2 sendok teh bawang putih bubuk"],
["Cincang halus bawang merah besar.","Campurkan semua bahan dalam mangkuk besar hingga tercampur rata.","Tutup dan dinginkan di lemari es setidaknya 30 menit dan hingga 24 jam.","Bagi campuran kalkun menjadi 4 porsi yang sama dan bentuk menjadi patty.","Masak dalam wajan antilengket yang dipanaskan dan diolesi semprotan masak antilengket, atau di atas panggangan. Patty matang saat suhu bagian dalam mencapai 165° F pada termometer daging."],
["Sajikan burger di dalam roti bun, roti gulung, atau di atas salad atau coleslaw (tidak termasuk dalam analisis nutrisi).","Jika tidak suka rasa pedas, gantilah cabai merah tumbuk dengan lada hitam.","Untuk diet rendah protein, bagi campuran kalkun menjadi 6 atau 8 patty."],
["3 daging","1/2 makanan pokok berpati"]),
R(2294,"Ayam Panggang dengan Isian Nasi",
"Untuk pertemuan Anda berikutnya, masaklah resep ramah ginjal Ayam Panggang dengan Isian Nasi.",
"6","4 ons ayam dan 1/3 cangkir nasi",
["1 ekor ayam utuh untuk dipanggang seberat 4 pon","2/3 cangkir beras parboiled, mentah","1 sendok makan saus Worcestershire","1 sendok makan minyak zaitun","1 sendok teh lada hitam","1/2 cangkir paprika hijau, dicincang","2 daun bawang, dicincang","1 cangkir potongan nanas, ditiriskan","1/4 cangkir jus nanas"],
["Panaskan oven terlebih dahulu hingga 350° F.","Bilas ayam dan keluarkan jeroan dari dalam rongga perut. Keringkan dengan tisu dapur dan olesi ayam dengan minyak.","Dalam mangkuk sedang, campurkan nasi, saus Worcestershire, minyak zaitun, lada hitam, paprika, daun bawang, nanas, dan jus nanas. Sendokkan campuran ke dalam rongga ayam sebagai isian.","Letakkan ayam dengan bagian dada menghadap ke atas dalam loyang pemanggang atau Dutch oven. Panggang tanpa ditutup selama 1-1/2 jam atau hingga suhu bagian dalam mencapai 180-185° F. Isian nasi harus mencapai setidaknya 165° F. Diamkan ayam 10-15 menit.","Sendokkan isian nasi dari rongga ayam dan letakkan di piring saji. Potong ayam menjadi beberapa bagian, letakkan di piring, lalu sajikan."],
["Jika ada sisa ayam, coba resep Chicken Lettuce Wraps dan Cool ‘n’ Crunchy Chicken Salad."],
["4 daging","1 makanan pokok berpati","1/2 buah, kalium rendah"]),
R(2295,"Shake Jeruk",
"Cepat, mudah, dan ramah ginjal. Semuanya ada dalam Shake Jeruk.",
"2","1-1/4 cangkir",
["1/2 cangkir jus nanas","1/2 cangkir susu almond tanpa pemanis","1 cangkir sherbet jeruk","1/2 cangkir produk telur rendah kolesterol"],
["Masukkan bahan-bahan ke dalam blender dan blender selama 30 detik.","Bagi menjadi 2 porsi.","Sajikan segera atau bekukan untuk nanti."],
["Produk telur rendah kolesterol sudah dipasteurisasi. Aman dikonsumsi tanpa dimasak. Jangan gunakan telur mentah.","Putih telur pasteurisasi dapat digunakan sebagai pengganti produk telur rendah kolesterol.","Susu beras dapat digunakan sebagai pengganti susu almond. Hindari pengganti susu yang mengandung zat tambahan fosfat."],
["1 daging","1/2 buah, kalium sedang","1/2 pengganti susu nonsusu","1 berkalori tinggi"]),
R(2296,"Daging Sapi dan Mi Creamy dengan Slow Cooker",
"Daging Sapi dan Mi Creamy dengan Crock-pot® menampilkan steak round yang mengenyangkan dan mi telur yang dilumuri saus creamy yang lumer di mulut. Hidangan ini sempurna untuk makan malam tinggi protein yang ramah ginjal.",
"5","3/4 cangkir daging sapi dengan saus, 1/2 cangkir mi",
["1 cangkir bawang bombai","3 siung bawang putih","1 pon steak top round","1 sendok makan peterseli kering","2 sendok makan mustard Dijon","1/2 sendok teh dill kering","1/2 sendok teh lada hitam","4 ons jamur iris kemasan","1/3 cangkir tepung terigu putih serbaguna","1 cangkir kaldu sapi rendah natrium","1/2 cangkir krim asam rendah lemak","8 ons mi telur, mentah"],
["Cincang bawang bombai dan haluskan bawang putih.","Potong steak menjadi irisan setebal 1/4″. Masukkan steak, bawang putih, bawang bombai, dan 5 bahan berikutnya ke dalam slow cooker listrik 3 quart. Aduk rata.","Sendokkan tepung perlahan ke dalam cangkir takar kering. Masukkan tepung ke dalam mangkuk kecil, dan tambahkan kaldu sedikit demi sedikit sambil diaduk dengan whisk hingga tercampur.","Tambahkan kaldu ke dalam slow cooker, dan aduk rata.","Tutup dengan penutup; masak dengan pengaturan tinggi selama 1 jam. Turunkan ke pengaturan api kecil, dan masak selama 7 hingga 8 jam atau hingga steak empuk.","Siapkan mi telur sesuai petunjuk kemasan, tanpa garam.","Matikan slow cooker, dan buka penutupnya. Diamkan campuran daging sapi selama 10 menit.","Aduk krim asam. Sajikan saus daging sapi di atas mi."],
["Kemasan mi telur 8 ons menghasilkan sekitar 2-1/2 cangkir mi matang.","Untuk diet rendah protein, jika Anda mengurangi porsi daging sapi dan saus menjadi 1/2 cangkir di atas 1/2 cangkir mi, proteinnya 20 gram per porsi (2 pilihan daging)."],
["3-1/2 daging","2 makanan pokok berpati","1/2 sayuran, kalium sedang"]),
R(2301,"Ayam dengan Saus Bawang Putih Panggang dan Jamur",
"Ayam dengan Saus Bawang Putih Panggang dan Jamur adalah hidangan ayam satu wajan yang mudah dan kaya rasa, rendah natrium dan tinggi protein untuk pasien dialisis. Untuk diet rendah protein, cukup belah setiap dada ayam menjadi dua dan sajikan dengan nasi atau pasta favorit Anda.",
"4","1/4 resep",
["2 kepala bawang putih","2 sendok teh minyak zaitun","4 dada ayam tanpa tulang dan tanpa kulit (sekitar 1-1/4 pon)","1/2 cangkir tepung terigu serbaguna","1/2 sendok teh daun thyme kering","1/2 sendok teh garam","1/4 sendok teh lada","1/4 cangkir mentega tanpa garam (1/2 batang)","1 cangkir jamur iris","1-1/2 cangkir kaldu ayam rendah natrium","1/2 cangkir susu murni"],
["Panaskan oven hingga 350°F.","Potong bagian atas setiap kepala bawang putih hingga siungnya terlihat. Letakkan kepala bawang putih dengan sisi potongan menghadap ke atas di atas selembar besar aluminium foil. Siram dengan minyak, lalu bungkus rapat dengan foil. Letakkan dalam loyang dan panggang 45 hingga 50 menit atau hingga bawang putih empuk. Dinginkan sebentar. Peras siung yang lembut dari kulitnya, cincang halus, lalu sisihkan.","Selagi bawang putih dipanggang, letakkan setiap dada ayam di antara 2 lembar plastik pembungkus; pukul perlahan dengan sisi datar pemukul daging hingga setebal sekitar 1/4 inci. Dalam loyang dangkal, campurkan tepung, thyme, garam, dan lada. Sisihkan 3 sendok makan tepung berbumbu untuk saus. Lumuri ayam dengan sisa campuran tepung.","Dalam wajan besar, panaskan 2 sendok makan mentega dengan api sedang-tinggi. Masak ayam selama 6-8 menit hingga bagian tengahnya tidak lagi merah muda (165°F dengan termometer), dibalik sekali. Pindahkan ayam ke piring dan tutup agar tetap hangat.","Dalam wajan yang sama, panaskan sisa mentega. Masak jamur dengan api sedang hingga sedikit kecokelatan. Taburkan tepung berbumbu yang disisihkan di atas jamur. Masak sambil diaduk sekitar 2 menit. Masukkan kaldu ayam, susu, dan bawang putih panggang. Didihkan. Kecilkan api; didihkan perlahan sekitar 3 menit atau hingga sedikit mengental.","Masukkan ayam ke dalam wajan berisi saus dan panaskan selama 1 hingga 2 menit."],
["Sajikan ayam dengan 1/3 cangkir nasi atau 1/2 cangkir pasta; masing-masing setara dengan sekitar 1 porsi karbohidrat.","Untuk porsi protein yang lebih rendah, potong dada ayam menjadi dua setelah dimasak."],
["4 daging","1 makanan pokok berpati","1/2 sayuran, kalium rendah"]),
R(2302,"Quiche Sayuran Mudah",
"Mulailah hari Anda dengan porsi sayuran saat sarapan yang tersamar dalam Quiche Sayuran Mudah yang lezat ini.",
"6","1/6 pai",
["1 buah zucchini besar","1 buah bawang bombai kecil","1 buah paprika sedang (merah, kuning, atau oranye)","1 sendok makan peterseli segar","1 kulit pai deep dish beku","4 sendok teh minyak zaitun","6 butir telur besar","3/4 cangkir susu almond tanpa pemanis","1 sendok makan tepung terigu serbaguna","1/4 sendok teh garam","1/4 sendok teh lada hitam","1/3 cangkir keju Parmesan parut"],
["Panaskan oven terlebih dahulu hingga 400° F. Parut zucchini. Cincang bawang bombai, paprika, dan peterseli. Panggang kulit pai sesuai petunjuk kemasan dan biarkan dingin.","Selagi kulit pai dipanggang, tambahkan 3 sendok teh minyak zaitun ke dalam wajan dan panaskan dengan api sedang-tinggi. Masukkan bawang bombai dan masak hingga lunak, sesekali diaduk. Tambahkan paprika dan zucchini. Lanjutkan","memasak sekitar 10 menit, sambil diaduk agar tidak gosong. Angkat dari kompor dan biarkan campuran dingin.","Kocok telur dalam mangkuk besar. Tambahkan susu almond, tepung, garam, dan lada hitam. Terus kocok hingga bahan tercampur.","Tambahkan sayuran matang dan peterseli ke campuran telur dan aduk hingga tercampur.","Tuang campuran ke dalam kulit pai yang telah dipanggang. Taburkan keju Parmesan di atasnya.","Letakkan kulit pai di atas loyang agar tidak tumpah. Panggang tanpa ditutup selama 35 hingga 40 menit, hingga bagian tengah quiche padat.","Biarkan dingin dan hias dengan peterseli jika diinginkan. Potong menjadi 6 bagian dan sajikan."],
["Untuk mengurangi natrium, hilangkan garam atau buat kulit pai buatan sendiri dengan garam yang lebih sedikit.","Sisa makanan dapat disimpan di lemari es selama 2 hingga 3 hari atau dibungkus dan dibekukan.","Jika menggunakan peterseli kering, kurangi jumlahnya menjadi 1 sendok teh."],
["1 daging","1 makanan pokok berpati","1 sayuran, kalium sedang","3 lemak"]),
R(2307,"Latte Protein Karamel",
"Semua orang suka memulai hari dengan secangkir kopi panas yang lezat. Namun daripada pergi ke kedai kopi langganan untuk secangkir kopi biasa, Anda dapat dengan mudah membuat resep ramah ginjal Latte Protein Karamel yang luar biasa di rumah. Latte ini tidak hanya terasa lezat, tetapi juga kaya protein untuk kesehatan yang lebih baik.",
"1","8 ons",
["1 sendok takar (20,5 g) bubuk protein whey","2 ons air","6 ons kopi panas","2 sendok makan DaVinci Gourmet® Caramel Sugar Free Syrup"],
["Masukkan 1 sendok takar bubuk protein ke dalam cangkir.","Tambahkan 2 ons air dan aduk hingga bubuk protein larut sepenuhnya.","Tambahkan 6 ons kopi panas dan aduk.","Tambahkan 2 sendok makan DaVinci Gourmet® Caramel Sugar Free Syrup. Sesuaikan dengan tingkat kemanisan yang diinginkan menggunakan pemanis bebas gula pilihan Anda."],
["Cocok sebagai minuman sarapan atau camilan tinggi protein.","DaVinci Gourmet® Caramel Sugar Free Syrup dapat dipesan secara daring jika tidak tersedia di pasar setempat.","Tanyakan kepada ahli gizi Anda tentang merek protein whey yang direkomendasikan. Simona menggunakan Optimum Nutrition® Any Whey Protein."],
["2 daging"]),
R(2308,"Rusk Swedia",
"Ahli gizi ginjal DaVita dari Minnesota membagikan beberapa resep daerah favorit mereka yang telah dimodifikasi untuk diet dialisis. Dengan membatasi fosfor, kalium, dan natrium, pasien dialisis dapat menikmati Rusk Swedia yang lezat.",
"36","1 potong",
["2 cangkir gula","1 cangkir mentega tanpa garam, dilunakkan","2 butir telur","1 cangkir krim asam","2 sendok teh ekstrak almond","4-1/2 cangkir tepung terigu putih serbaguna","1 sendok teh soda kue","1/2 sendok teh baking powder","semprotan masak antilengket"],
["Dalam mangkuk besar, campurkan semua bahan hingga terbentuk adonan kaku. Tutup dan dinginkan di lemari es setidaknya 4 jam.","Panaskan oven terlebih dahulu hingga 325° F.","Semprot loyang jelly roll dengan semprotan masak antilengket. Tekan adonan ke dalam loyang.","Masukkan ke dalam oven dan panggang selama 45 menit.","Keluarkan dari oven dan biarkan dingin selama 5 menit.","Buat irisan 1” melintang pada loyang jelly roll (arah yang pendek). Potong setiap bagian memanjang menjadi 3 potong sehingga totalnya 36 rusk. Balikkan setiap irisan pada sisinya di atas loyang.","Panggang tambahan 45 menit pada suhu 275° F.","Matikan oven dan biarkan rusk di dalam oven semalaman (atau setidaknya 8 jam). Rusk yang sudah matang akan menyerupai biscotti.","Sajikan bersama kopi pagi atau sebagai camilan kapan saja."],
["Sebagai alternatif, adonan dapat dibentuk menjadi 2 roti persegi panjang alih-alih ditekan ke dalam loyang jelly roll. Iris menjadi potongan 1”, letakkan dengan sisi potongan menghadap ke bawah dan lanjutkan memanggang."],
["1-1/2 makanan pokok berpati","1 lemak"]),
R(2310,"Wrap Tortilla",
"Butuh ide baru untuk makan siang, makan malam, atau camilan saat menjalani diet ginjal? Cobalah Wrap Tortilla, alternatif lezat dan sehat dari ahli gizi DaVita, Janie. Wrap yang mudah dibuat ini berisi sayuran renyah dan pilihan ayam, kalkun, atau daging sapi yang digulung menjadi satu, sehingga praktis dibawa bepergian.",
"2","1 wrap",
["2 sendok makan wortel","2 sendok makan paprika hijau","1/3 cangkir mentimun","2/3 cangkir daging ayam matang tanpa garam","2 tortilla tepung, ukuran 6″","4 sendok makan krim keju kocok","1/4 sendok teh bawang putih bubuk","1/4 sendok teh bawang bombai bubuk","1/3 cangkir campuran slaw brokoli"],
["Parut wortel. Cincang paprika hijau dan mentimun. Suwir ayam.","Campurkan bawang putih dan bawang bombai bubuk ke dalam krim keju.","Oleskan setengah campuran di atas setiap tortilla.","Tambahkan sayuran dan daging.","Gulung wrap dan dinginkan di lemari es atau sajikan segera."],
["Buat lebih dahulu dan simpan di lemari es hingga 2 hari.","Cocok dengan roti pipih jenis apa pun.","Tampak lezat jika dipotong menjadi dua dan disusun di piring bersama blueberry dan stroberi segar. Tambahkan segelas limun peras segar yang dingin.","Campuran coleslaw dapat menggantikan slaw brokoli dan wortel parut, atau coba sayuran rendah kalium lainnya sebagai pengganti.","Untuk variasi, cobalah kalkun atau daging sapi panggang sebagai pengganti ayam."],
["2 daging","1 makanan pokok berpati","1 sayuran, kalium rendah"]),
]
save(7,recs)
